mapper.select:
SELECT bulletin_board_id , bulletin_board_title , system_code , bulletin_board_type_code , bb_short_reply_enabled_flag , bb_reply_enabled_flag , bb_attach_file_enable_flag , bb_use_flag FROM LGCOM_BOARD_MASTER_M WHERE 1 = 1
AND system_code = #{systemCode}
AND bulletin_board_id = #{boardId}
AND bulletin_board_title LIKE #{boardName} || '%'
AND bb_use_flag = #{useFlag}
ORDER BY system_code, bulletin_board_title

mapper.update:
UPDATE LGCOM_BOARD_MASTER_M
   SET bulletin_board_title        = #{bulletinBoardTitle}
     , bulletin_board_type_code    = #{bulletinBoardTypeCode}
     , bb_short_reply_enabled_flag = NVL(#{bbShortReplyEnabledFlag},'N')
     , bb_reply_enabled_flag       = NVL(#{bbReplyEnabledFlag},'N')
     , bb_attach_file_enable_flag  = NVL(#{bbAttachFileEnableFlag},'N')
     , bb_use_flag                 = #{bbUseFlag}
     , last_updated_by             = #{sessionUserId}
     , last_update_date            = SYSDATE
 WHERE bulletin_board_id           = #{bulletinBoardId}
   AND system_code                 = #{systemCode}
